<script setup lang="ts">import {onMounted,ref} from 'vue';import {request} from '../../api/http';const hospital=ref<any>(null),error=ref('');onMounted(async()=>{try{hospital.value=(await request<any>({url:'/public/hospital'})).data;}catch{error.value='医院信息暂不可用';}});function go(url:string){uni.navigateTo({url});}</script><template><view class="page"><view v-if="hospital" class="hero"><text class="eyebrow">专业 · 便捷 · 安心</text><text class="title">{{hospital.name}}</text><text class="description">{{hospital.introduction||'医院公开信息由后台统一维护。'}}</text><text>{{hospital.serviceHotline||hospital.telephone}}</text></view><view v-else class="notice">{{error||'正在加载医院信息…'}}</view><view class="grid"><button @click="go('/pages/booking/index')">预约挂号</button><button @click="go('/pages/patient/index')">患者中心</button><button @click="go('/pages/prescriptions/index')">我的处方</button><button @click="go('/pages/diagnostic-reports/index')">检查检验</button><button @click="go('/pages/campuses/index')">院区导航</button><button @click="go('/pages/departments/index')">医疗科室</button><button @click="go('/pages/doctors/index')">医生团队</button></view><view class="notice">已支持预约、处方与已发布检查检验报告查询。</view></view></template><style scoped>.page{padding:32rpx}.hero{background:linear-gradient(135deg,#e1f4fa,#edf4ff);padding:64rpx 40rpx;border-radius:24rpx}.eyebrow,.title,.description{display:block}.eyebrow{color:#167597;font-size:28rpx}.title{font-size:48rpx;font-weight:700;margin:20rpx 0}.description{color:#5f7180;font-size:30rpx;line-height:1.7}.notice{margin-top:28rpx;padding:28rpx;background:#fff;border-radius:16rpx;color:#5f7180}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:16rpx;margin-top:28rpx}button{font-size:28rpx;background:#fff;color:#166b8d}</style>
